/**
 * @param {...(string[] | undefined)} groups
 */
function mergeReferenceUrls(...groups: Array<string[] | undefined>): string[] {
	return Array.from(
		new Set(
			groups
				.flat()
				.filter((value): value is string => typeof value === 'string' && value.trim().length > 0)
				.map((value) => value.trim()),
		),
	);
}

/**
 * @param {{ roles: string[]; stats: { label: string; value: string }[] }} defaults
 * @param {{ slug: string; referenceUrls?: string[] } & Record<string, unknown>} seed
 * @returns {PersonProfileRecord}
 */
function buildBulkProfile(defaults: ProfileDefaults, seed: ProfileSeed): PersonProfileRecord {
	const fallbackMeta = bulkProfileReferenceUrls[seed.slug];
	const fallbackProfileImage =
		fallbackMeta && typeof fallbackMeta === 'object' && !Array.isArray(fallbackMeta)
			? fallbackMeta.profileImage
			: undefined;
	const fallbackReferenceUrls = Array.isArray(fallbackMeta)
		? fallbackMeta
		: fallbackMeta && typeof fallbackMeta === 'object'
			? fallbackMeta.referenceUrls
			: undefined;

	return {
		...seed,
		profileImage: seed.profileImage ?? fallbackProfileImage ?? bulkProfileImageUrls[seed.slug],
		roles: defaults.roles,
		spotlight: seed.spotlight ?? 'Figura conectada al catalogo editorial actual de Cine Posta.',
		biography: seed.biography ?? [],
		editorialBiography: seed.editorialBiography ?? [],
		editorialStatus: seed.editorialStatus ?? 'pending',
		stats: defaults.stats.map((stat) => ({ ...stat })),
		referenceUrls: mergeReferenceUrls(seed.referenceUrls, fallbackReferenceUrls),
	};
}

/**
 * @param {{ roles: string[]; stats: { label: string; value: string }[] }} defaults
 * @param {Array<Record<string, unknown> & { slug: string }>} seeds
 */
function buildBulkProfiles(defaults: ProfileDefaults, seeds: ProfileSeed[]): Record<string, PersonProfileRecord> {
	return Object.fromEntries(seeds.map((seed) => [seed.slug, buildBulkProfile(defaults, seed)]));
}

function getCatalogBackedProfileMeta(slug: string) {
	return catalogBackedProfileMeta[slug];
}

function buildCatalogBackedProfile(defaults: ProfileDefaults, seed: ProfileSeed): PersonProfileRecord {
	const profileMeta = getCatalogBackedProfileMeta(seed.slug);
	const fallbackMeta = bulkProfileReferenceUrls[seed.slug];
	const fallbackProfileImage =
		fallbackMeta && typeof fallbackMeta === 'object' && !Array.isArray(fallbackMeta)
			? fallbackMeta.profileImage
			: undefined;
	const fallbackReferenceUrls = Array.isArray(fallbackMeta)
		? fallbackMeta
		: fallbackMeta && typeof fallbackMeta === 'object'
			? fallbackMeta.referenceUrls
			: undefined;
	const spotlight =
		seed.spotlight ??
		'Su nombre sigue funcionando como una referencia inmediata para el tipo de cine con el que el catalogo ya lo conecta.';

	return {
		...seed,
		profileImage: seed.profileImage ?? profileMeta?.profileImage ?? fallbackProfileImage ?? bulkProfileImageUrls[seed.slug],
		roles: defaults.roles,
		spotlight,
		biography: seed.biography ?? [],
		editorialBiography: seed.editorialBiography ?? [],
		editorialStatus: seed.editorialStatus ?? 'pending',
		stats: defaults.stats.map((stat) => ({ ...stat })),
		referenceUrls: mergeReferenceUrls(
			seed.referenceUrls,
			mergeReferenceUrls(profileMeta?.referenceUrls, fallbackReferenceUrls),
		),
	};
}

function buildCatalogBackedProfiles(defaults: ProfileDefaults, seeds: ProfileSeed[]): Record<string, PersonProfileRecord> {
	return Object.fromEntries(seeds.map((seed) => [seed.slug, buildCatalogBackedProfile(defaults, seed)]));
}

function shouldMergeBiographyFragment(paragraph: string): boolean {
	return /(?:\b[A-Z]\.|;\s*n\.|,\s*n\.)$/u.test(paragraph.trim());
}

function normalizeBiographyParagraphs(biography: PersonProfileRecord['biography']): string[] {
	const paragraphs = Array.isArray(biography) ? biography.filter((entry) => entry.trim().length > 0) : [];
	const normalized: string[] = [];

	for (const paragraph of paragraphs) {
		if (normalized.length > 0 && shouldMergeBiographyFragment(normalized[normalized.length - 1])) {
			normalized[normalized.length - 1] = `${normalized[normalized.length - 1]} ${paragraph}`;
			continue;
		}

		normalized.push(paragraph);
	}

	return normalized;
}

function formatKnownForTitle(slug: string): string {
	const lowerWords = new Set(['a', 'and', 'de', 'del', 'el', 'en', 'for', 'la', 'las', 'los', 'of', 'the', 'to', 'y']);
	const title = slug
		.replace(/-\d{4}$/u, '')
		.split('-')
		.filter(Boolean)
		.map((word, index) => {
			if (index > 0 && lowerWords.has(word)) {
				return word;
			}

			return `${word.charAt(0).toUpperCase()}${word.slice(1)}`;
		})
		.join(' ');

	return title
		.replace(/\bIi\b/gu, 'II')
		.replace(/\bIii\b/gu, 'III')
		.replace(/\bIv\b/gu, 'IV')
		.replace(/\bM3gan\b/gu, 'M3GAN')
		.replace(/\bX Men\b/gu, 'X-Men')
		.replace(/\bDc\b/gu, 'DC')
		.replace(/\bMcu\b/gu, 'MCU');
}

function formatKnownForList(knownFor: PersonProfileRecord['knownFor']): string {
	const titles = knownFor.slice(0, 3).map(formatKnownForTitle);

	if (titles.length === 0) {
		return 'varios titulos del catalogo';
	}

	if (titles.length === 1) {
		return titles[0];
	}

	if (titles.length === 2) {
		return `${titles[0]} y ${titles[1]}`;
	}

	return `${titles.slice(0, -1).join(', ')} y ${titles[titles.length - 1]}`;
}

function formatRolesForBiography(roles: PersonProfileRecord['roles']): string {
	const primaryRole = roles[0]?.toLowerCase() ?? 'figura';
	return primaryRole === 'dirección' ? 'director' : primaryRole;
}

function buildCatalogBiography(profile: PersonProfileRecord): string[] {
	const roleLabel = formatRolesForBiography(profile.roles);
	const knownForLabel = formatKnownForList(profile.knownFor);
	const originCopy = profile.birthPlace ? ` con origen en ${profile.birthPlace}` : '';
	const award = profile.awards[0];
	const awardCopy = award
		? ` Entre sus reconocimientos destacados figura ${award.label}${award.category ? ` en ${award.category}` : ''}${award.work ? ` por ${award.work}` : ''}${award.year ? ` en ${award.year}` : ''}.`
		: ' Su trayectoria se entiende mejor al mirar la continuidad entre presencia de pantalla, oficio y titulos asociados.';

	return [
		`${profile.name} es ${roleLabel}${originCopy}. ${profile.headline}`,
		`Su recorrido se puede ubicar a partir de ${knownForLabel}, titulos que muestran que tipo de presencia aporta: estrella reconocible, interprete de genero, figura autoral o pieza clave de una franquicia.`,
		`${profile.spotlight} La biografia queda enfocada en trayectoria, premios y peliculas relacionadas para evitar que el perfil sea apenas una linea de ficha tecnica.${awardCopy}`,
	];
}

const minimumBiographyParagraphs = 3;
const minimumBiographyCharacters = 2508;

function getDraftHash(value: string): number {
	return Array.from(value).reduce((hash, character) => ((hash * 31) + character.charCodeAt(0)) >>> 0, 7);
}

function formatDeathLine(name: string): string | undefined {
	const person = (peopleCatalog as Record<string, { deathDate?: string; deathYear?: number }>)[name];
	if (!person?.deathDate && !person?.deathYear) return undefined;
	if (!person.deathDate) return `Murió en ${person.deathYear}.`;

	const [year, month, day] = person.deathDate.split('-').map(Number);
	const months = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
	return year && month && day ? `Murió el ${day} de ${months[month - 1]} de ${year}.` : `Murió en ${person.deathYear ?? year}.`;
}

function buildEditorialDraft(profile: PersonProfileRecord): string[] {
	const hash = getDraftHash(profile.slug);
	const role = profile.roles.join(', ').toLowerCase();
	const origin = profile.birthPlace ? `Nació en ${profile.birthPlace}. ` : '';
	const knownFor = formatKnownForList(profile.knownFor);
	const knownForVerb = profile.knownFor.length === 1 ? 'sirve' : 'sirven';
	const pronoun = profile.roles.some((entry) => entry.toLowerCase() === 'actriz') ? 'la' : 'lo';
	const deathLine = formatDeathLine(profile.name);
	const verb = deathLine ? 'trabajó' : 'trabaja';
	const identityVerb = deathLine ? 'fue' : 'es';
	const award = profile.awards[0];
	const awardFact = award
		? `${award.label}${award.category ? `: ${award.category}` : ''}${award.work ? ` por ${award.work}` : ''}${award.year ? ` (${award.year})` : ''}`
		: 'sus créditos destacados';
	const opening = [
		`${origin}${profile.name} ${verb} como ${role}. ${profile.headline}`,
		`${profile.name} ${identityVerb} ${role}.${profile.birthPlace ? ` Su origen está en ${profile.birthPlace}.` : ''} ${profile.headline}`,
		`${origin}La trayectoria de ${profile.name} reúne trabajo como ${role}. ${profile.headline}`,
		`${profile.name} construyó una carrera como ${role}.${profile.birthPlace ? ` Nació en ${profile.birthPlace}.` : ''} ${profile.headline}`,
	][hash % 4];
	const titleSentence = [
		`Dentro del catálogo, ${knownFor} ${knownForVerb} para ubicar los títulos que mejor recortan ese recorrido.`,
		`El catálogo de Cine Posta ${pronoun} conecta especialmente con ${knownFor}, una selección concreta antes que una filmografía interminable.`,
		`Para seguir esa línea de trabajo, la ficha enlaza ${knownFor}, películas que muestran distintos momentos de su recorrido.`,
		`Las películas conectadas —${knownFor}— ofrecen una entrada directa a la parte de su carrera que el sitio puede documentar.`,
	][Math.floor(hash / 5) % 4];
	const closing = [
		`${profile.spotlight} Entre los reconocimientos que la ficha registra figura ${awardFact}.`,
		`${profile.spotlight} Un dato verificable para leer esa trayectoria es ${awardFact}.`,
		`${profile.spotlight} La ficha destaca ${awardFact}, sin convertir el perfil en una lista de premios.`,
		`${profile.spotlight} También queda señalado ${awardFact}, como referencia puntual del reconocimiento obtenido.`,
	][Math.floor(hash / 23) % 4];
	const individualClosing = closing.startsWith(profile.name) ? closing : `${profile.name}: ${closing}`;
	return [`${opening} ${titleSentence}`, [individualClosing, deathLine].filter(Boolean).join(' ')];
}

function ensureBiographyDepth(profile: PersonProfileRecord): PersonProfileRecord {
	const biography = normalizeBiographyParagraphs(profile.biography);
	const biographyLength = biography.join(' ').length;

	if (biography.length >= minimumBiographyParagraphs && biographyLength >= minimumBiographyCharacters) {
		return {
			...profile,
			biography,
			editorialBiography: profile.editorialBiography?.length ? profile.editorialBiography : buildEditorialDraft(profile),
			editorialStatus: profile.editorialStatus ?? 'approved',
		};
	}

	const catalogBiography = buildCatalogBiography(profile);
	const expandedBiography =
		biography.length === 0
			? catalogBiography
			: [
					...biography,
					...catalogBiography.filter((paragraph) => !biography.some((entry) => entry.includes(paragraph.slice(0, 32)))),
				].slice(0, 4);

	return {
		...profile,
		biography: expandedBiography,
		editorialBiography: profile.editorialBiography?.length ? profile.editorialBiography : buildEditorialDraft(profile),
		editorialStatus: profile.editorialStatus ?? 'approved',
	};
}

